import{_ as i,z as e,m as l,ap as t}from"./chunks/framework.40Eg4YuW.js";const b=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/quick-start.md","filePath":"markdown/quick-start.md","lastUpdated":1785843060000}'),o={name:"markdown/quick-start.md"};function r(s,a,d,h,n,c){return l(),e("div",null,a[0]||(a[0]=[t('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><h2 id="安装插件" tabindex="-1">安装插件 <a class="header-anchor" href="#安装插件" aria-label="Permalink to &quot;安装插件&quot;">​</a></h2><h3 id="通过-koishi-控制台安装-通用" tabindex="-1">通过 Koishi 控制台安装（通用） <a class="header-anchor" href="#通过-koishi-控制台安装-通用" aria-label="Permalink to &quot;通过 Koishi 控制台安装（通用）&quot;">​</a></h3><ol><li>打开 Koishi 控制台</li><li>进入插件市场</li><li>搜索</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">adapter-bilibili-dm</span></span></code></pre></div><ol start="4"><li>点击安装</li></ol><img src="https://i0.hdslb.com/bfs/openplatform/ccf09979c5dc0174a462f38dc900cd87c91f925b.png" alt="market" referrerpolicy="no-referrer" width="500"><h3 id="通过命令行安装-项目模板" tabindex="-1">通过命令行安装（项目模板） <a class="header-anchor" href="#通过命令行安装-项目模板" aria-label="Permalink to &quot;通过命令行安装（项目模板）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#61AFEF;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#98C379;"> koishi-plugin-adapter-bilibili-dm</span></span></code></pre></div><h2 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to &quot;基础配置&quot;">​</a></h2><h3 id="_1-获取-bilibili-uid" tabindex="-1">1. 获取 Bilibili UID <a class="header-anchor" href="#_1-获取-bilibili-uid" aria-label="Permalink to &quot;1. 获取 Bilibili UID&quot;">​</a></h3><p>在配置插件之前，您需要获取您的 Bilibili 账号 UID。</p><h4 id="手机端获取方法" tabindex="-1">手机端获取方法 <a class="header-anchor" href="#手机端获取方法" aria-label="Permalink to &quot;手机端获取方法&quot;">​</a></h4><img src="https://i0.hdslb.com/bfs/openplatform/9168ed872d8d132ee32d265b17327bbda5d40588.png" alt="手机端获取方法" referrerpolicy="no-referrer" width="500"><h4 id="web端获取方法" tabindex="-1">WEB端获取方法 <a class="header-anchor" href="#web端获取方法" aria-label="Permalink to &quot;WEB端获取方法&quot;">​</a></h4><img src="https://i0.hdslb.com/bfs/openplatform/44f38e9a76c90cc6ceba563931ea5fe67a034dca.png" alt="WEB端获取方法" referrerpolicy="no-referrer" width="500"><h3 id="_2-配置插件" tabindex="-1">2. 配置插件 <a class="header-anchor" href="#_2-配置插件" aria-label="Permalink to &quot;2. 配置插件&quot;">​</a></h3><ol><li>在 Koishi 控制台中找到 <code>adapter-bilibili-dm</code> 插件</li><li>在 <code>selfId</code> 中填入准备登录的 Bilibili 账号 UID</li><li>启用插件</li></ol><p><code>selfId</code> 必须是扫码账号的 UID。适配器会在扫码得到 Cookie 后再次校验账号；如果扫码账号与配置项不一致，插件不会关闭，但前端会提示“扫码账号和配置项账号不一致，请更换账号”。</p><h3 id="_3-登录认证" tabindex="-1">3. 登录认证 <a class="header-anchor" href="#_3-登录认证" aria-label="Permalink to &quot;3. 登录认证&quot;">​</a></h3><p>插件启用后，需要进行登录认证：</p><ol><li>在插件配置页面会显示二维码</li><li>等待页面显示“请使用手机扫描二维码”</li><li>使用 Bilibili APP 扫描二维码</li><li>页面显示“二维码已扫描，请在手机上确认登录”后，在手机端确认登录</li><li>登录成功后 Cookie 会保存到本地，后续重启会优先使用缓存自动登录</li></ol><p>二维码通常约两分钟后过期。二维码过期后，请在插件页面重新发起登录或刷新二维码。</p><img src="https://i0.hdslb.com/bfs/openplatform/d3f604c1b732ff83f0874ee89027dda8e4c3031a.png" alt="登录认证" referrerpolicy="no-referrer" width="500"><h2 id="验证安装" tabindex="-1">验证安装 <a class="header-anchor" href="#验证安装" aria-label="Permalink to &quot;验证安装&quot;">​</a></h2><p>配置完成后，你可以：</p><ol><li>在 Koishi 控制台查看适配器状态</li><li>向机器人发送一条测试私信（例如 <code>help</code>、<code>inspect</code>）</li><li>在视频评论区或图文动态评论区 @ 机器人并发送指令</li><li>检查是否能正常接收消息并回复私信或评论</li></ol><blockquote><p>注意： 消息接收延迟 受轮询速率影响。</p></blockquote>',28)]))}const f=i(o,[["render",r]]);export{b as __pageData,f as default};
